use super::*;
#[wasm_bindgen]extern "C"{#[wasm_bindgen(js_namespace=ufBridge,js_name=selectScene)]fn select_scene(data:&str);#[wasm_bindgen(js_namespace=ufBridge,js_name=setEditMode)]fn set_edit_mode(data:&str);#[wasm_bindgen(js_namespace=ufBridge,js_name=layoutEditor)]fn layout_editor(data:&str);}
pub fn clear_highlight(){select_scene("null");}
pub fn sync(){STATE.with(|cell|{let a=cell.borrow();select_scene(&a.selection.to_string());set_edit_mode(&json!({"moving":a.moving,"placing":a.placing,"insertKind":a.insert_kind,"insertRotation":a.insert_rotation,"handles":(["dollhouse","framing"].contains(&a.view.as_str())&&!a.draw_walls&&!a.placing&&a.moving.is_empty()),"drawWalls":a.draw_walls,"wallEdge":a.wall_edge}).to_string());layout_editor(&a.selection.to_string());});}
fn collections(a:&State)->(Vec<Wall>,Vec<staging::Furniture>){(serde_json::from_value(a.m["walls"].clone()).unwrap(),serde_json::from_value(a.m["furniture"].clone()).unwrap())}
fn placement_target(a:&State,t:&Value)->Value{
 let(ws,fs)=collections(a);
 let mut f=if let Some(f)=fs.iter().find(|f|f.id==a.moving){f.clone()}else{let(w,d)=edit::item_dimensions(&a.insert_kind);staging::Furniture{id:"preview".into(),kind:a.insert_kind.clone(),room_id:"custom".into(),x:0.,z:0.,w,d,rotation:a.insert_rotation,local_width:w,local_depth:d}};
 let requested_x=t["requestedX"].as_f64().unwrap_or(n(t,"x"));let requested_z=t["requestedZ"].as_f64().unwrap_or(n(t,"z"));f.x=requested_x;f.z=requested_z;f.rotation=t["draftRotation"].as_f64().unwrap_or(a.insert_rotation);
 let(f,snapped,error)=edit::snap_item(f,&a.c,&ws,&fs);let mut target=t.clone();target["kind"]=json!("floor");target["requestedX"]=json!(requested_x);target["requestedZ"]=json!(requested_z);target["x"]=json!(f.x);target["z"]=json!(f.z);target["placement"]=json!(f);target["placementError"]=json!(error);target["snapped"]=json!(snapped);target
}
fn preview_target(a:&mut State){if s(&a.selection,"kind")=="floor"{a.selection=placement_target(a,&a.selection)}}
pub fn placement(input:&str)->String{let Ok(t)=serde_json::from_str::<Value>(input)else{return "null".into()};STATE.with(|cell|{let a=cell.borrow();if !["dollhouse","framing"].contains(&a.view.as_str())||a.draw_walls{return "null".into()}placement_target(&a,&t).to_string()})}
pub fn configure(id:&str){STATE.with(|cell|{let mut a=cell.borrow_mut();if ["edit-item","place-kind"].contains(&id){a.insert_kind=val(id);if id=="place-kind"{a.moving.clear();}}else{let angle=parsed(id);if angle.is_finite(){a.insert_rotation=angle.rem_euclid(360.).to_radians();}}if ["floor","furniture"].contains(&s(&a.selection,"kind")){a.selection["draftRotation"]=json!(a.insert_rotation);preview_target(&mut a);}a.message.clear();});render(false);}
fn save_wall(a:&mut State,w:Wall)->Result<(),String>{
 let(ws,fs)=collections(a);if !w.exterior{edit::moved_wall(&w,&a.c,0.,0.,&ws)?;}
 if fs.iter().any(|f|f.kind!="rug"&&!edit::clear_of_walls(f,std::slice::from_ref(&w))){return Err("Move the furniture away from this wall line first.".into())}
 a.c.wall_adjustments.insert(w.id.clone(),WallGeometry{x:w.x,z:w.z,length:w.length,axis:w.axis.clone()});a.c.opening_overrides.insert(w.id.clone(),w.openings.clone());changed(a);wall_selected(a,w);Ok(())
}
fn snap_wall_edge(w:&Wall,edge:&str,coordinate:f64)->f64{let anchor=(if w.axis=="x"{w.x}else{w.z})+(if edge=="start"{w.length}else{0.});anchor+((coordinate-anchor)/2.).round()*2.}
pub fn resize(input:&str){input::suppress_scene_click();let Ok(t)=serde_json::from_str::<Value>(input)else{return};let mut redraw=false;STATE.with(|cell|{let mut a=cell.borrow_mut();if ["start","end"].contains(&s(&t,"edge")){a.wall_edge=s(&t,"edge").into();}let(ws,_)=collections(&a);let Some(w)=ws.iter().find(|w|w.id==s(&t,"wallId"))else{return};let result=if s(&t,"operation")=="move"{edit::moved_wall(w,&a.c,grid(n(&t,"x"))-w.x,grid(n(&t,"z"))-w.z,&ws)}else{edit::resized_wall(w,&a.c,s(&t,"edge"),snap_wall_edge(w,s(&t,"edge"),n(&t,"coordinate")))};match result.and_then(|w|save_wall(&mut a,w)){Ok(())=>redraw=true,Err(error)=>a.message=error}});render(redraw);}
fn permitted(a:&State,t:&Value)->bool{a.view!="exterior"||(["wall","opening"].contains(&s(t,"kind"))&&a.m["walls"].as_array().unwrap().iter().any(|w|s(w,"id")==s(t,"wallId")&&w["exterior"]==true))}
pub fn view_changed(a:&mut State){if !["dollhouse","framing"].contains(&a.view.as_str()){a.draw_walls=false;a.placing=false;a.moving.clear();}if !permitted(a,&a.selection){a.selection=Value::Null;}}
fn commit_item(a:&mut State,mut f:staging::Furniture)->Result<(),String>{
 let(ws,fs)=collections(a);if f.kind=="stairs"{if f.id=="preview"&&a.c.active_floor!=0{return Err("Place stairs on the main floor; they connect to the upper floor automatically.".into())}if f.id=="preview"&&a.c.placed_furniture.iter().any(|f|f.kind=="stairs"){return Err("This house already has stairs. Click them to move, rotate or delete them.".into())}let rotation=f.rotation;edit::rotate_item(&mut f,rotation);}if let Some(error)=edit::item_error(&f,&a.c,&ws,&fs){return Err(error)}
 if f.id=="preview"{f.id=unique("F-U",a.c.active_floor);}
 f.room_id=a.m["rooms"].as_array().unwrap().iter().find(|r|f.x>=n(r,"x")&&f.x<=n(r,"x")+n(r,"w")&&f.z>=n(r,"z")&&f.z<=n(r,"z")+n(r,"d")).map(|r|s(r,"id").to_string()).unwrap_or_else(||"custom".into());
 a.insert_kind=f.kind.clone();a.insert_rotation=f.rotation;a.c.placed_furniture.retain(|o|o.id!=f.id);if !a.c.deleted_furniture.contains(&f.id){a.c.deleted_furniture.push(f.id.clone());}a.c.placed_furniture.push(f);changed(a);if a.insert_kind=="stairs"{a.placing=false;}reset_selection(a);Ok(())
}
pub fn pick(input:&str){input::suppress_scene_click();let Ok(mut target)=serde_json::from_str::<Value>(input)else{return};let mut redraw=false;STATE.with(|cell|{let mut a=cell.borrow_mut();
 // In the exterior view every floor's outside walls are clickable: picking an upper wall switches to that floor.
 if a.view=="exterior"&&["wall","opening"].contains(&s(&target,"kind")){let id=s(&target,"wallId");let floor=if id.ends_with("-L3"){2}else if id.ends_with("-L2"){1}else{0};if floor!=a.c.active_floor&&floor<a.c.stories{a.c.active_floor=floor;changed(&mut a);redraw=true;}}
 if !permitted(&a,&target){reset_selection(&mut a);return}if s(&target,"kind")=="wall"{if s(&a.selection,"wallId")!=s(&target,"wallId"){a.wall_edge="end".into();}if let Some(w)=a.m["walls"].as_array().unwrap().iter().find(|w|s(w,"id")==s(&target,"wallId")){let width=2f64.min(n(w,"length"));let at=(n(&target,"at")-width/2.).clamp(0.,(n(w,"length")-width).max(0.));target["sectionAt"]=json!(at);target["sectionWidth"]=json!(width);target["wall"]=w.clone();a.wall=s(w,"id").into();}}if s(&target,"kind")=="floor"{target["draftRotation"]=json!(a.insert_rotation);target=placement_target(&a,&target);if target["commit"]==true{let f=serde_json::from_value(target["placement"].clone()).unwrap();match commit_item(&mut a,f){Ok(())=>{redraw=true;return},Err(e)=>a.message=e}}}a.selection=target;});render(redraw);}
fn num(id:&str,label:&str,value:f64)->String{number(id,label,value,0.,100.)}
fn item_select(value:&str)->String{let mut out=String::from("<label class=field>Insert item<select id=edit-item>");for(key,label)in[("stairs","Stairs · two-story blank slate"),("sofa","Sofa"),("bed","Bed"),("chair","Dining chair"),("armchair","Lounge chair"),("toilet","Toilet"),("vanity","Vanity"),("shower","Shower"),("kitchen","Kitchen cabinets"),("island","Island"),("counter-run","Kitchen counter run"),("pantry-tower","Tall pantry cabinet"),("fridge","Refrigerator"),("dining","Dining table"),("coffee","Coffee table"),("desk","Desk"),("wardrobe","Wardrobe"),("nightstand","Nightstand"),("laundry","Washer / dryer"),("plant","Plant"),("rug","Rug"),("floorlamp","Floor lamp"),("side-table","Side table"),("bench","Upholstered bench"),("bookcase","Bookcase"),("entry-console","Console table"),("floor-vase","Sculptural vase"),("floor-mirror","Standing mirror"),("tall-plant","Tall plant")]{out.push_str(&format!("<option value={} {}>{}</option>",key,selected(key,value),label));}for group in ["Living","Dining","Bedroom","Bath","Kitchen","Study","Entry","Decor"]{out.push_str(&format!("<optgroup label=\"{}\">",group));for item in objects::all().iter().filter(|o|o.group==group){out.push_str(&format!("<option value=\"{}\" {}>{}</option>",item.kind,selected(&item.kind,value),esc(&item.name)));}out.push_str("</optgroup>");}out.push_str("</select></label>");out}
fn angle(id:&str,value:f64)->String{format!("<label class=field>Rotation · degrees<input id={} type=number min=0 max=360 step=15 value={:.0}></label>",id,value.to_degrees().rem_euclid(360.))}
fn rotation(value:f64)->String{format!("{}<div class=rotation-buttons><button data-action=edit-rotate-left>↶ 15°</button><button data-action=edit-rotate-right>↷ 15°</button><button data-action=edit-rotate-quarter>↷ 90°</button></div>",angle("edit-rotation",value))}
fn stair_rotation(value:f64)->String{format!("{}<div class=rotation-buttons><button data-action=edit-rotate-left>↶ Turn left 90°</button><button data-action=edit-rotate-right>↷ Turn right 90°</button><button data-action=edit-rotate-half>⟲ Turn around 180°</button></div>",angle("edit-rotation",value))}
/// What "＋ Place object" puts down, shown beside it in the Interior and Framing toolbars.
pub fn chooser(a:&State)->String{format!("<span class=place-chooser>{}{}</span>",item_select(&a.insert_kind).replace("id=edit-item","id=place-kind"),angle("place-angle",a.insert_rotation))}
pub fn menu(a:&State)->String{let t=&a.selection;if t.is_null()||!permitted(a,t){return String::new()}let kind=s(t,"kind");let title=match kind{"wall"=>"Wall section","opening"=>"Door / window","furniture"=>"Furniture / fixture",_=>"Insert here"};let mut o=format!("<section class=context-menu role=dialog aria-label=\"3D edit menu\"><div class=context-heading data-menu-drag><div><strong>{}</strong><span class=context-drag-hint>Drag to move</span></div><button data-action=edit-cancel aria-label=\"Close edit menu\">×</button></div><div class=context-body>",title);let feedback=if let Some(e)=t["placementError"].as_str(){e}else{&a.message};if !feedback.is_empty(){o.push_str(&format!("<p class=context-feedback role=status>{}</p>",esc(feedback)));}
 match kind{
 "wall"|"opening"=>{let wall=t.get("wall").cloned().or_else(||a.m["walls"].as_array().unwrap().iter().find(|w|s(w,"id")==s(t,"wallId")).cloned()).unwrap_or(Value::Null);let existing=if kind=="opening"{wall["openings"].as_array().and_then(|os|os.iter().find(|o|s(o,"id")==s(t,"id"))).cloned().unwrap_or(Value::Null)}else{Value::Null};let is_existing=!existing.is_null();let default_kind=if is_existing{s(&existing,"kind")}else{"window"};let width=if is_existing{n(&existing,"width")}else{3.};let at=if is_existing{n(&existing,"at")}else{(n(t,"at")-width/2.).max(0.4).min((n(&wall,"length")-width-0.4).max(0.4))};let bottom=if is_existing{n(&existing,"bottom")}else{3.};let height=if is_existing{n(&existing,"height")}else{4.};o.push_str(&format!("<p class=context-location>{} · {:.0} ft long</p>",esc(s(&wall,"name")),n(&wall,"length")));
 if !is_existing{if wall["exterior"]!=true{o.push_str(&btn("edit-bearing",if a.c.bearing_walls.contains(&s(&wall,"id").to_string()){"Bearing wall · switch to partition"}else{"Partition · mark as bearing wall"},"secondary wide"));o.push_str("<div class=two-fields>");for(id,label,value)in[("edit-wall-x","Wall X · ft",n(&wall,"x")),("edit-wall-z","Wall Z · ft",n(&wall,"z")),("edit-wall-length","Length · ft",n(&wall,"length"))]{o.push_str(&num(id,label,value).replace("step=0.01","step=2"));}o.push_str("</div>");o.push_str(&btn("edit-save-wall","Move / resize wall","primary wide"));o.push_str("<div class=rotation-buttons><button data-action=edit-wall-left>↶ 90°</button><button data-action=edit-wall-right>↷ 90°</button><button data-action=edit-wall-flip>Flip 180°</button></div>");}o.push_str("<div class=wall-edge-buttons><span>Resize end</span>");for(edge,label)in[("start","Start"),("end","End")]{o.push_str(&format!("<button data-action=edit-edge-{} aria-pressed=\"{}\">{}</button>",edge,a.wall_edge==edge,label));}o.push_str("</div><p class=context-hint>Gold ends extend or shorten the wall. The teal middle handle moves an interior wall sideways or along its length. Arrow keys move; Shift + arrows resize the chosen end. Stair approaches stay protected.</p><details class=context-opening><summary>Add a window, door or passage</summary>");}
 o.push_str(&format!("<label class=field>Opening type<select id=edit-opening-kind>{}</select></label>",opts(&strings(&["window","door","passage"]),default_kind)));o.push_str(&format!("<label class=field id=edit-window-size-field{}>Window size<select id=edit-window-size data-wall-height={}>{}</select></label>",if default_kind=="window"{""}else{" hidden"},a.c.wall_height,opts(&strings(&WINDOW_SIZES.iter().map(|w|w.0).collect::<Vec<_>>()),WINDOW_SIZES.iter().find(|w|default_kind=="window"&&near(w.1,width)&&near(w.2,height)).map_or("Custom",|w|w.0))));o.push_str("<div class=two-fields>");for(id,label,value)in[("edit-at","Start · ft",at),("edit-width","Width · ft",width),("edit-bottom","Sill · ft",bottom),("edit-height","Height · ft",height)]{o.push_str(&num(id,label,value));}o.push_str("</div><p class=context-hint>Door and window height guardrails remain active. Product clear opening and local approval require review.</p><div class=context-choices>");o.push_str(&btn(if is_existing{"edit-save-opening"}else{"edit-insert-opening"},if is_existing{"Yes, update"}else{"Yes, insert"},"primary"));o.push_str(&btn("edit-cancel","No","secondary"));if !is_existing{o.push_str("</div></details>");}else{o.push_str("</div>");}
if !is_existing{o.push_str(&bump_and_dormer(a,&wall));}
o.push_str("<details class=context-delete><summary>");o.push_str(if is_existing{"Delete this opening?"}else{"Delete the highlighted wall section?"});o.push_str("</summary>");if !is_existing{o.push_str("<div class=two-fields>");o.push_str(&num("edit-section-at","Section start · ft",n(t,"sectionAt")));o.push_str(&num("edit-section-width","Length to remove · ft",n(t,"sectionWidth")));o.push_str("</div><label class=check><input id=edit-entire-wall type=checkbox>Remove the entire wall</label>");}o.push_str("<div class=context-choices>");o.push_str(&btn("edit-delete","Yes, delete","danger"));o.push_str(&btn("edit-cancel","No","secondary"));o.push_str("</div></details>");},
 "furniture"=>{if let Some(f)=a.m["furniture"].as_array().unwrap().iter().find(|f|s(f,"id")==s(t,"id")){o.push_str(&format!("<p class=context-location>{} · {}</p>",esc(s(f,"kind")),esc(s(f,"roomId"))));o.push_str("<div class=two-fields>");for(id,label,value)in[("edit-x","Position X · ft",n(f,"x")),("edit-z","Position Z · ft",n(f,"z")),("edit-width","Width · ft",n(f,"localWidth")),("edit-depth","Depth · ft",n(f,"localDepth"))]{o.push_str(&num(id,label,value));}o.push_str("</div>");let turn=t["draftRotation"].as_f64().unwrap_or(n(f,"rotation"));o.push_str(&if s(f,"kind")=="stairs"{stair_rotation(turn)}else{rotation(turn)});o.push_str("<div class=context-choices>");o.push_str(&btn("edit-save-item","Apply changes","primary"));o.push_str(&btn("edit-move",if s(f,"kind")=="stairs"{"Move stairs with a click"}else{"Move with a click"},"secondary"));o.push_str("</div><details class=context-delete><summary>Delete this item?</summary><div class=context-choices>");o.push_str(&btn("edit-delete","Yes, delete","danger"));o.push_str(&btn("edit-cancel","No","secondary"));o.push_str("</div></details>");}},
 _=>{o.push_str(&format!("<p class=context-location>Snapped position · {:.2}, {:.2} ft</p>",n(t,"x"),n(t,"z")));let f=a.m["furniture"].as_array().unwrap().iter().find(|f|s(f,"id")==a.moving);if let Some(f)=f{o.push_str(&format!("<p class=context-hint>Moving {}. Click a different floor position to adjust the destination.</p><input id=edit-item type=hidden value=\"{}\">",esc(s(f,"kind")),esc(s(f,"kind"))));}else{o.push_str(&item_select(&a.insert_kind));}o.push_str(&if a.insert_kind=="stairs"{stair_rotation(t["placement"]["rotation"].as_f64().unwrap_or(a.insert_rotation))}else{rotation(t["placement"]["rotation"].as_f64().unwrap_or(a.insert_rotation))});o.push_str("<div class=context-choices>");o.push_str(&btn("edit-insert-item",if a.moving.is_empty(){"Yes, insert here"}else{"Yes, move here"},"primary"));o.push_str(&btn("edit-cancel","No","secondary"));o.push_str("</div><details class=context-wall><summary>Add a wall here</summary><label class=field>Direction<select id=edit-axis><option value=x>Across (X)</option><option value=z>Along (Z)</option></select></label>");o.push_str(&num("edit-length","Wall length · ft",4.));o.push_str(&btn("edit-add-wall","Yes, add wall","primary wide"));o.push_str("</details><p class=context-hint>Use Place object for one-click placement. Green footprints snap to nearby space; blue zones keep circulation clear.</p>");}
 }o.push_str("</div></section>");o}
/// The side of the house an outside wall faces, as (bump-out side, dormer side).
fn house_side(wall_id:&str)->Option<(&'static str,&'static str)>{match wall_id.split("-L").next().unwrap_or(""){"E1"=>Some(("front","Front")),"E2"=>Some(("rear","Rear")),"E3"=>Some(("left","Left")),"E4"=>Some(("right","Right")),_=>None}}
/// The bump-out a bump-out wall belongs to (its index in bumps::list).
fn bump_index(wall_id:&str)->Option<usize>{wall_id.split("-wingb").nth(1)?.chars().take_while(char::is_ascii_digit).collect::<String>().parse().ok()}
/// On an outside wall: add an 8 ft bump-out (ground floor) or a dormer above it. On a bump-out wall: remove it.
fn bump_and_dormer(a:&State,wall:&Value)->String{
 let id=s(wall,"id");let mut o=String::new();
 if let Some(i)=bump_index(id){if bumps::list(&a.c).get(i).is_some(){o.push_str("<details class=context-opening open><summary>This wall is part of a bump-out</summary>");o.push_str(&btn("edit-remove-bump","Remove this bump-out","danger wide"));o.push_str("</details>");}return o}
 if house_side(id).is_none(){return o}
 o.push_str("<details class=context-opening><summary>Add a bump-out or dormer here</summary>");
 if a.c.active_floor==0&&a.c.design_mode!="Blank slate"{
  let depth=if a.c.bump_depth>0.{a.c.bump_depth}else{4.};
  o.push_str(&format!("<label class=field>Bump-out depth<select id=edit-bump-depth>{}</select></label>",[2.,4.,6.,8.].iter().map(|d:&f64|format!("<option value={d} {}>{d} ft out · 8 ft wide</option>",if near(*d,depth){"selected"}else{""})).collect::<String>()));
  o.push_str(&btn("edit-add-bump","Add a bump-out here","primary wide"));
 }
 o.push_str(&btn("edit-add-dormer","Add a dormer on the roof above","secondary wide"));
 o.push_str("<p class=context-hint>A bump-out opens into the room behind it and gets its own roof; it needs 8 ft of wall clear of doors, the garage and a balcony. A dormer goes on this side's roof slope, as close to here as the roof allows.</p></details>");
 o
}
fn parsed(id:&str)->f64{val(id).parse().unwrap_or(f64::NAN)}
fn unique(prefix:&str,floor:usize)->String{thread_local!{static SEQ:std::cell::Cell<u32>=const {std::cell::Cell::new(0)};}let seq=SEQ.with(|s|{s.set(s.get().wrapping_add(1));s.get()});format!("{}{}-{}{}",prefix,(js_sys::Date::now()as u64)%1_000_000_000,seq,floor_tag(floor))}
fn reset_selection(a:&mut State){a.selection=Value::Null;a.moving.clear();}
pub fn act(target:Element){let command=target.get_attribute("data-action").unwrap_or_default();let mut redraw=false;STATE.with(|cell|{let mut a=cell.borrow_mut();let t=a.selection.clone();match command.as_str(){
 "edit-cancel"=>{reset_selection(&mut a);a.placing=false;a.draw_walls=false;},
 "undo"|"redo"=>redraw=history(&mut a,&command),
 "edit-draw"=>{a.draw_walls=!a.draw_walls;a.placing=false;reset_selection(&mut a);},
 "edit-edge-start"|"edit-edge-end"=>a.wall_edge=if command.ends_with("start"){"start"}else{"end"}.into(),
 "edit-stairs"=>{if a.c.stories<2{a.message="Choose two or three stories before adding stairs.".into();return}a.c.active_floor=0;a.m=fresh(&a.c);a.insert_kind="stairs".into();a.insert_rotation=0.;a.placing=true;a.draw_walls=false;a.view="dollhouse".into();reset_selection(&mut a);redraw=true;},
 "edit-bearing"=>{let id=s(&t,"wallId").to_string();if a.c.bearing_walls.contains(&id){a.c.bearing_walls.retain(|v|v!=&id)}else{a.c.bearing_walls.push(id);}changed(&mut a);a.message="Bearing designation updated. Joist spans and preliminary sizing recalculated; support approval is pending.".into();redraw=true;},
 "edit-place"=>{a.placing=!a.placing;a.draw_walls=false;reset_selection(&mut a);if a.view!="dollhouse"{a.view="dollhouse".into();redraw=true;}},
 "edit-move"=>{a.placing=false;a.draw_walls=false;a.insert_rotation=a.m["furniture"].as_array().unwrap().iter().find(|f|s(f,"id")==s(&t,"id")).map(|f|n(f,"rotation")).unwrap_or(0.);a.moving=s(&t,"id").into();a.selection=Value::Null;a.message="Click the floor where you want to move this item.".into();},
 "edit-delete"=>{match s(&t,"kind"){
 "wall"=>{let wall=a.m["walls"].as_array().unwrap().iter().find(|w|s(w,"id")==s(&t,"wallId")).cloned().unwrap_or(Value::Null);let whole=doc().get_element_by_id("edit-entire-wall").and_then(|e|e.dyn_into::<HtmlInputElement>().ok()).is_some_and(|e|e.checked());let at=if whole{0.}else{parsed("edit-section-at")};let width=if whole{n(&wall,"length")}else{parsed("edit-section-width")};if !at.is_finite()||!width.is_finite()||width<0.45||at<0.||at+width>n(&wall,"length")+0.001{a.message="The selected section must fit the wall and be at least 6 inches long.".into();return}a.c.wall_removals.push(WallRemoval{wall_id:s(&t,"wallId").into(),at,width});},
 "opening"=>{if let Some(w)=a.m["walls"].as_array().unwrap().iter().find(|w|s(w,"id")==s(&t,"wallId")){let mut os:Vec<Opening>=serde_json::from_value(w["openings"].clone()).unwrap();os.retain(|o|o.id!=s(&t,"id"));a.c.opening_overrides.insert(s(&t,"wallId").into(),os);}},
 "furniture"=>{let id=s(&t,"id").to_string();a.c.deleted_furniture.push(id.clone());a.c.placed_furniture.retain(|f|f.id!=id);},_=>{}}changed(&mut a);reset_selection(&mut a);a.message="Removed. Model, framing and quantities updated. Undo is available.".into();redraw=true;},
 "edit-save-opening"|"edit-insert-opening"=>{let Some(w)=a.m["walls"].as_array().unwrap().iter().find(|w|s(w,"id")==s(&t,"wallId")).cloned()else{return};let mut os:Vec<Opening>=serde_json::from_value(w["openings"].clone()).unwrap();if command=="edit-save-opening"{os.retain(|o|o.id!=s(&t,"id"))}let kind=val("edit-opening-kind");os.push(Opening{id:if command=="edit-save-opening"{s(&t,"id").into()}else{unique("U",a.c.active_floor)},bottom:if kind=="window"{parsed("edit-bottom")}else{0.},height:parsed("edit-height"),kind,at:parsed("edit-at"),width:parsed("edit-width")});let wall:Wall=serde_json::from_value(w.clone()).unwrap();let rooms:Vec<Room>=serde_json::from_value(a.m["rooms"].clone()).unwrap();let mut error=rules::opening_error(&os,&wall,&a.c,&rooms);
 // A new opening dropped by click onto an existing one slides to the nearest free spot on the same wall;
 // a start position the visitor typed is kept and reported instead.
 let untouched=doc().get_element_by_id("edit-at").is_some_and(|e|!e.has_attribute("data-typed"));if error.is_some()&&command=="edit-insert-opening"&&untouched{let asked=os.last().unwrap().at;for step in 1..=((wall.length*4.)as usize){let mut done=false;for sign in [1.,-1.]{let mut trial=os.clone();trial.last_mut().unwrap().at=asked+sign*step as f64*0.25;if rules::opening_error(&trial,&wall,&a.c,&rooms).is_none(){os=trial;error=None;done=true;break}}if done{break}}}
 if error.is_none(){a.c.opening_overrides.insert(s(&w,"id").into(),os);changed(&mut a);reset_selection(&mut a);redraw=true;}else{a.message=error.unwrap();}},
 "edit-add-bump"=>{let Some((side,_))=house_side(s(&t,"wallId"))else{return};let at=n(&t,"at");let depth=parsed("edit-bump-depth");
  a.c.custom_bumps.push(bumps::CustomBump{side:side.into(),at,depth});
  let placed=validate(&a.c).is_ok()&&bumps::list(&a.c).iter().any(|b|b.side==side&&((b.lo+b.hi)/2.-at).abs()<=4.5);
  if placed{changed(&mut a);reset_selection(&mut a);a.message=format!("Bump-out added: 8 ft wide, {depth} ft out.");redraw=true;}else{a.c.custom_bumps.pop();a.message="A bump-out doesn't fit here. It needs 8 ft of wall at least 2 ft from the corners, clear of doors, the garage, a balcony and other bump-outs.".into();}},
 "edit-add-dormer"=>{let Some((_,side))=house_side(s(&t,"wallId"))else{return};let at=n(&t,"at");
  a.c.custom_dormers.push(additions::dormers::CustomDormer{side:side.into(),at});
  let notes=model::build(&a.c)["dormerNotes"].to_string();
  if validate(&a.c).is_ok()&&!notes.contains("No room for the added"){changed(&mut a);reset_selection(&mut a);a.message=format!("Dormer added on the {} roof.",side.to_lowercase());redraw=true;}else{a.c.custom_dormers.pop();a.message="A dormer doesn't fit on this roof slope here: it is too low, too close to a hip or valley, or another dormer is in the way.".into();}},
 "edit-remove-bump"=>{let Some(i)=bump_index(s(&t,"wallId"))else{return};let list=bumps::list(&a.c);if i>=list.len(){return}
  // Keep every other bump-out where it is, as one the visitor placed, and stop adding new ones automatically.
  a.c.custom_bumps=list.iter().enumerate().filter(|(j,_)|*j!=i).map(|(_,b)|bumps::CustomBump{side:b.side.into(),at:(b.lo+b.hi)/2.,depth:b.depth}).collect();a.c.bump_outs="None".into();
  changed(&mut a);reset_selection(&mut a);a.message="Bump-out removed.".into();redraw=true;},
 "edit-add-wall"=>{let along=val("edit-axis")=="x";let length=grid(parsed("edit-length"));let x=grid((t["requestedX"].as_f64().unwrap_or(n(&t,"x"))-if along{length/2.}else{0.}).max(0.));let z=grid((t["requestedZ"].as_f64().unwrap_or(n(&t,"z"))-if along{0.}else{length/2.}).max(0.));let(ws,fs)=collections(&a);match edit::drawn_wall(unique("I-C",a.c.active_floor),&a.c,x,z,x+if along{length}else{0.},z+if along{0.}else{length},&ws){Ok(w)=>{if fs.iter().any(|f|f.kind!="rug"&&!edit::clear_of_walls(f,std::slice::from_ref(&w))){a.message="Move furniture away from this wall line first.".into();return}a.c.added_walls.push(w);changed(&mut a);reset_selection(&mut a);redraw=true;},Err(e)=>a.message=e}},
 "edit-save-item"|"edit-insert-item"=>{
 let f=if command=="edit-save-item"{let Some(mut f)=a.m["furniture"].as_array().unwrap().iter().find(|f|s(f,"id")==s(&t,"id")).and_then(|f|serde_json::from_value::<staging::Furniture>(f.clone()).ok())else{return};
  // A piece resized in place keeps its back where it was (against the wall) and grows into the room, instead of
  // growing from its center into the wall behind it; typed X/Z positions are used exactly as entered.
  let moved=["edit-x","edit-z"].iter().any(|id|doc().get_element_by_id(id).is_some_and(|e|e.has_attribute("data-typed")));
  let grow=parsed("edit-depth")-f.local_depth;let rotation=parsed("edit-rotation").to_radians();
  f.x=parsed("edit-x");f.z=parsed("edit-z");if !moved&&grow.is_finite()&&f.kind!="stairs"{f.x-=rotation.sin()*grow/2.;f.z+=rotation.cos()*grow/2.;}
  f.local_width=parsed("edit-width");f.local_depth=parsed("edit-depth");edit::rotate_item(&mut f,rotation);
  // If that exact spot is blocked, the nearest clear spot nearby is used, as when placing.
  let(ws,fs)=collections(&a);if edit::item_error(&f,&a.c,&ws,&fs).is_some(){let(snapped,_,error)=edit::snap_item(f.clone(),&a.c,&ws,&fs);if error.is_none(){f=snapped;}}
  f}else{a.insert_rotation=parsed("edit-rotation").to_radians();if a.moving.is_empty(){a.insert_kind=val("edit-item");}let mut point=t.clone();point["draftRotation"]=json!(a.insert_rotation);let target=placement_target(&a,&point);a.selection=target.clone();serde_json::from_value(target["placement"].clone()).unwrap()};
 match commit_item(&mut a,f){Ok(())=>redraw=true,Err(error)=>a.message=error}
 },
 "edit-save-wall"|"edit-wall-left"|"edit-wall-right"|"edit-wall-flip"=>{
 let(ws,_)=collections(&a);let Some(w)=ws.iter().find(|w|w.id==s(&t,"wallId"))else{return};
 let result=if command=="edit-save-wall"{let coordinate=if w.axis=="x"{w.x}else{w.z};edit::resized_wall(w,&a.c,"end",coordinate+grid(parsed("edit-wall-length"))).and_then(|resized|edit::moved_wall(&resized,&a.c,grid(parsed("edit-wall-x"))-w.x,grid(parsed("edit-wall-z"))-w.z,&ws))}else{edit::rotated_wall(w,&a.c,if command=="edit-wall-left"{-1}else if command=="edit-wall-flip"{2}else{1},&ws)};
 match result.and_then(|w|save_wall(&mut a,w)){Ok(())=>redraw=true,Err(error)=>a.message=error}
 },
 "edit-rotate-left"|"edit-rotate-right"|"edit-rotate-quarter"|"edit-rotate-half"=>{
 // Stairs turn in quarter turns: left and right 90°, or 180° to face the other way.
 let stairs=a.m["furniture"].as_array().unwrap().iter().any(|f|s(f,"id")==s(&t,"id")&&s(f,"kind")=="stairs")||(s(&t,"kind")=="floor"&&a.insert_kind=="stairs");
 let delta=match(command.as_str(),stairs){("edit-rotate-left",true)=>-90.,("edit-rotate-right",true)=>90.,("edit-rotate-half",_)=>180.,("edit-rotate-left",_)=>-15.,("edit-rotate-quarter",_)=>90.,_=>15.};redraw=rotate_selection(&mut a,delta);
 },_=>{}}});render(redraw);STATE.with(|cell|select_scene(&cell.borrow().selection.to_string()));}

fn rotate_selection(a:&mut State,degrees:f64)->bool{
 if s(&a.selection,"kind")=="furniture"{let Some(mut f)=a.m["furniture"].as_array().unwrap().iter().find(|f|s(f,"id")==s(&a.selection,"id")).and_then(|f|serde_json::from_value::<staging::Furniture>(f.clone()).ok())else{return false};let id=f.id.clone();let rotation=f.rotation+degrees.to_radians();edit::rotate_item(&mut f,rotation);let(ws,fs)=collections(a);let(f,_,error)=edit::snap_item(f,&a.c,&ws,&fs);if let Some(error)=error{a.message=error;return false}match commit_item(a,f){Ok(())=>{a.selection=json!({"kind":"furniture","id":id});true},Err(e)=>{a.message=e;false}}
 }else{a.insert_rotation=(a.insert_rotation+degrees.to_radians()).rem_euclid(std::f64::consts::TAU);if s(&a.selection,"kind")=="floor"{a.selection["draftRotation"]=json!(a.insert_rotation);preview_target(a);}false}
}

/// Window presets for the opening editor: (label, width, height, sill) in feet.
pub const WINDOW_SIZES:[(&str,f64,f64,f64);5]=[("Custom",0.,0.,0.),("Small · 2 × 3 ft",2.,3.,3.5),("Medium · 3 × 4.5 ft",3.,4.5,2.75),("Large · 4 × 5.5 ft",4.,5.5,2.),("Picture · 6 × 5 ft",6.,5.,2.5)];
pub fn window_size(){let pick=val("edit-window-size");let Some(&(_,w,h,sill))=WINDOW_SIZES.iter().find(|p|p.0==pick&&p.1>0.)else{return};
 // Fit the preset under this wall's header: lower the sill to 2 ft first, then shorten the window.
 let wall=doc().get_element_by_id("edit-window-size").and_then(|e|e.get_attribute("data-wall-height")).and_then(|v|v.parse::<f64>().ok()).unwrap_or(8.);let room=wall-0.25-9.25/12.;let sill=sill.min(room-h).max(2.);let h=((room-sill)*4.).floor().min(h*4.)/4.;if let Some(e)=doc().get_element_by_id("edit-opening-kind").and_then(|e|e.dyn_into::<web_sys::HtmlSelectElement>().ok()){e.set_value("window");}
 for(id,value)in[("edit-bottom",sill),("edit-height",h),("edit-width",w)]{if let Some(e)=doc().get_element_by_id(id).and_then(|e|e.dyn_into::<HtmlInputElement>().ok()){e.set_value(&if crate::units::metric(){crate::units::num(value*crate::units::FT,2)}else{value.to_string()});}}}
pub fn opening_kind(){let kind=val("edit-opening-kind");if let Some(f)=doc().get_element_by_id("edit-window-size-field"){if kind=="window"{let _=f.remove_attribute("hidden");}else{let _=f.set_attribute("hidden","");}}for(id,value)in if kind=="window"{[("edit-bottom",3.),("edit-height",4.),("edit-width",3.)]}else{[("edit-bottom",0.),("edit-height",82.5/12.),("edit-width",38./12.)]}{if let Some(e)=doc().get_element_by_id(id).and_then(|e|e.dyn_into::<HtmlInputElement>().ok()){e.set_value(&if crate::units::metric(){crate::units::num(value*crate::units::FT,2)}else{value.to_string()});}}}

fn history(a:&mut State,command:&str)->bool{
 let next=if command=="undo"{a.undo.pop()}else{a.redo.pop()};let Some(mut c)=next else{return false};
 let floor=a.c.active_floor;let current=a.c.clone();if command=="undo"{a.redo.push(current)}else{a.undo.push(current)}
 c.active_floor=floor.min(c.stories-1);a.c=c;a.previous=a.c.clone();a.m=fresh(&a.c);reset_selection(a);a.message.clear();true
}
fn wall_selected(a:&mut State,w:Wall){a.wall=w.id.clone();a.selection=json!({"kind":"wall","wallId":w.id,"wall":w,"at":w.length/2.,"sectionAt":0.,"sectionWidth":w.length,"screenX":a.selection["screenX"],"screenY":a.selection["screenY"]});}
pub fn draw(input:&str){
 input::suppress_scene_click();
 let Ok(t)=serde_json::from_str::<Value>(input)else{return};let mut redraw=false;
 STATE.with(|cell|{let mut a=cell.borrow_mut();if !a.draw_walls||!["dollhouse","framing"].contains(&a.view.as_str()){return}
 let ws:Vec<Wall>=serde_json::from_value(a.m["walls"].clone()).unwrap();
 match edit::drawn_wall(unique("I-C",a.c.active_floor),&a.c,n(&t,"x1"),n(&t,"z1"),n(&t,"x2"),n(&t,"z2"),&ws){
 Ok(w)=>{if a.m["furniture"].as_array().unwrap().iter().filter_map(|f|serde_json::from_value::<staging::Furniture>(f.clone()).ok()).any(|f|f.kind!="rug"&&!edit::clear_of_walls(&f,std::slice::from_ref(&w))){a.message="Move the furniture away from this wall line first.".into();return}
 a.c.added_walls.push(w);changed(&mut a);reset_selection(&mut a);redraw=true},Err(e)=>a.message=e}
 });render(redraw);
}
pub fn keyboard(e:&web_sys::KeyboardEvent)->bool{
 if e.default_prevented(){return true}
 if let Some(t)=e.target().and_then(|t|t.dyn_into::<Element>().ok()){if ["INPUT","SELECT","TEXTAREA"].contains(&t.tag_name().as_str())||t.closest("[contenteditable=true]").ok().flatten().is_some(){return false}}
 let key=e.key();let shortcut=(e.ctrl_key()||e.meta_key())&&key.eq_ignore_ascii_case("z");
 let mut handled=false;let mut redraw=false;
 STATE.with(|cell|{let mut a=cell.borrow_mut();
 if shortcut{handled=true;redraw=history(&mut a,if e.shift_key(){"redo"}else{"undo"});return}
 if a.draw_walls||!["dollhouse","framing"].contains(&a.view.as_str())||e.ctrl_key()||e.meta_key()||e.alt_key(){return}
 if key.eq_ignore_ascii_case("r"){handled=true;redraw=rotate_selection(&mut a,if e.shift_key(){90.}else{15.});return}
 let(dx,dz)=match key.as_str(){"ArrowLeft"=>(-2.,0.),"ArrowRight"=>(2.,0.),"ArrowUp"=>(0.,2.),"ArrowDown"=>(0.,-2.),_=>return};
 let t=a.selection.clone();let kind=s(&t,"kind");
 if kind=="opening"{let Some(w)=a.m["walls"].as_array().unwrap().iter().find(|w|s(w,"id")==s(&t,"wallId")).and_then(|w|serde_json::from_value::<Wall>(w.clone()).ok())else{return};handled=true;let delta=if w.axis=="x"{dx}else{dz};if delta==0.{a.message="Use left/right for this opening, or front/back on a wall running front to rear.".into();return}let mut os=w.openings.clone();let Some(opening)=os.iter_mut().find(|o|o.id==s(&t,"id"))else{return};opening.at+=delta/2.;let rooms:Vec<Room>=serde_json::from_value(a.m["rooms"].clone()).unwrap();if let Some(error)=rules::opening_error(&os,&w,&a.c,&rooms){a.message=error;return}a.c.opening_overrides.insert(w.id.clone(),os);changed(&mut a);a.selection["wall"]=a.m["walls"].as_array().unwrap().iter().find(|wall|s(wall,"id")==w.id).unwrap().clone();redraw=true;
 }else if kind=="wall"{let Some(w)=a.m["walls"].as_array().unwrap().iter().find(|w|s(w,"id")==s(&t,"wallId")).and_then(|w|serde_json::from_value::<Wall>(w.clone()).ok())else{return};handled=true;
 let ws:Vec<Wall>=serde_json::from_value(a.m["walls"].clone()).unwrap();
 let result=if e.shift_key(){let delta=if w.axis=="x"{dx}else{dz};if delta==0.{a.message="Use left/right for this wall, or front/back for a wall running front to rear.".into();return}let coordinate=(if w.axis=="x"{w.x}else{w.z})+(if a.wall_edge=="end"{w.length}else{0.})+delta;edit::resized_wall(&w,&a.c,&a.wall_edge,coordinate)}else{edit::moved_wall(&w,&a.c,dx,dz,&ws)};
 match result{Ok(w)=>{let fs:Vec<staging::Furniture>=serde_json::from_value(a.m["furniture"].clone()).unwrap();if fs.iter().any(|f|f.kind!="rug"&&!edit::clear_of_walls(f,std::slice::from_ref(&w))){a.message="Move the furniture away from this wall line first.".into();return}a.c.wall_adjustments.insert(w.id.clone(),WallGeometry{x:w.x,z:w.z,length:w.length,axis:w.axis.clone()});a.c.opening_overrides.insert(w.id.clone(),w.openings.clone());changed(&mut a);wall_selected(&mut a,w);redraw=true},Err(error)=>a.message=error}
 }else if kind=="furniture"{let Some(mut f)=a.m["furniture"].as_array().unwrap().iter().find(|f|s(f,"id")==s(&t,"id")).and_then(|f|serde_json::from_value::<staging::Furniture>(f.clone()).ok())else{return};handled=true;let step=if e.shift_key(){0.5}else{0.125};f.x+=dx*step;f.z+=dz*step;let ws:Vec<Wall>=serde_json::from_value(a.m["walls"].clone()).unwrap();let fs:Vec<staging::Furniture>=serde_json::from_value(a.m["furniture"].clone()).unwrap();if let Some(error)=edit::item_error(&f,&a.c,&ws,&fs){a.message=error;return}a.c.placed_furniture.retain(|other|other.id!=f.id);if !a.c.deleted_furniture.contains(&f.id){a.c.deleted_furniture.push(f.id.clone());}a.c.placed_furniture.push(f);changed(&mut a);redraw=true;}
 });if handled{e.prevent_default();render(redraw)}handled
}
